using System;using System.IO;using System.Linq;using System.Text;using DownloadRepair;using Mono.Cecil;using Mono.Cecil.Cil;
class ThemeTests {
    static int count;static void Ok(bool b,string text){if(!b)throw new Exception(text);count++;Console.WriteLine("PASS "+text);}static void Reject(Action action,string text){bool failed=false;try{action();}catch{failed=true;}Ok(failed,text);}
    static string Child(string dir,string name,byte[] bytes){string folder=Path.Combine(dir,name);Directory.CreateDirectory(folder);string path=Path.Combine(folder,"PCL.exe");File.WriteAllBytes(path,bytes);return path;}
    static int Main(string[] args){try{Dependency.Install();Run(args);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
    static void Run(string[] args){byte[] source=File.ReadAllBytes(args[0]);string root=Path.GetFullPath(args[1]);Directory.CreateDirectory(root);string hash=FileSafety.Hash(source);string original=Child(root,"copy",source);var core=FileSafety.Inspect(original);var themes=FileSafety.Inspect(original,true);
        Ok(!core.ThemesRequested&&!core.ThemesAlreadyUnlocked,"themes are opt-in by default");Ok(themes.ThemesRequested&&!themes.Complete&&FileSafety.Hash(themes.Output)!=FileSafety.Hash(core.Output),"optional theme plan produces separate output");
        string copy=Path.Combine(Path.GetDirectoryName(original),"PCL.themes.exe");FileSafety.CreateCopy(original,copy,true);byte[] output=File.ReadAllBytes(copy);Ok(ThemePatcher.IsUnlocked(output)&&FileSafety.Inspect(copy,true).Complete,"theme copy contains verified theme marker");Ok(FileSafety.Hash(File.ReadAllBytes(original))==hash,"theme copy preserves source");
        using(var before=SemanticPatcher.Read(core.Output))using(var after=SemanticPatcher.Read(output)){
            var a=SemanticPatcher.MethodShapes(before);var b=SemanticPatcher.MethodShapes(after);var changed=a.Keys.Where(k=>a[k]!=b[k]).ToArray();Ok(changed.Length==3,"only three cosmetic methods changed after core repair");
            foreach(string method in new[]{"get_CurrentRank","get_HasUpdatePermission","InputPotatoCode","CheckPotatoCode","ThemeUnlock"}) { var keys=a.Keys.Where(k=>k.Contains("PCL.ModSecret::"+method+"(")).ToArray();Ok(keys.Length==1&&keys.All(k=>a[k]==b[k]),method+" left unchanged"); }
            var secret=SemanticPatcher.Type(after,"PCL.ModSecret");var refresh=SemanticPatcher.Method(secret,"ThemeRefresh",1);Ok(refresh.Body.Instructions.Any(i=>i.OpCode==OpCodes.Switch&&((Instruction[])i.Operand).Length==15)&&refresh.Body.Instructions[0].OpCode==OpCodes.Ldsfld,"full palette switching restored, no forced default argument");
            var check=SemanticPatcher.Method(secret,"ThemeCheckOne",1);Ok(check.Body.Instructions.Count==2&&check.Body.Instructions[0].OpCode==OpCodes.Ldc_I4_1,"theme eligibility is cosmetic-only unconditional");
            var task=SemanticPatcher.Method(secret,"ThemeCheckAll",1);var reference=(MethodReference)task.Body.Instructions.Single(i=>i.OpCode==OpCodes.Ldftn).Operand;var ui=SemanticPatcher.Type(after,reference.DeclaringType.FullName).Methods.Single(x=>x.FullName==reference.FullName);
            Ok(Enumerable.Range(0,15).All(n=>ui.Body.Instructions.Any(i=>i.Operand is MethodReference&&((MethodReference)i.Operand).Name=="get_RadioLauncherTheme"+n)),"all fifteen visible theme controls enabled");Ok(ui.Body.ExceptionHandlers.Count==1&&ui.Body.ExceptionHandlers[0].HandlerType==ExceptionHandlerType.Finally,"animation state restored in finally");
        }
        Ok(FileSafety.Hash(ThemePatcher.Apply(output).Bytes)==FileSafety.Hash(output),"theme application idempotent");Reject(()=>FileSafety.CreateCopy(original,copy,true),"theme copy refuses existing output");
        string inplace=Child(root,"inplace",source);FileSafety.Apply(inplace,false,true);FileSafety.Restore(inplace);Ok(FileSafety.Hash(File.ReadAllBytes(inplace))==hash,"theme in-place repair restores exact original");
        string upgrade=Child(root,"core-upgrade",source);FileSafety.Apply(upgrade,false);FileSafety.Apply(upgrade,false,true);Ok(FileSafety.Inspect(upgrade,true).Complete,"core-only repair can add themes");FileSafety.Restore(upgrade);Ok(FileSafety.Hash(File.ReadAllBytes(upgrade))==hash,"theme upgrade reuses original baseline for full restore");
        byte[] corrupt;using(var m=SemanticPatcher.Read(output)){var refresh=SemanticPatcher.Method(SemanticPatcher.Type(m,"PCL.ModSecret"),"ThemeRefresh",1);refresh.Body.Instructions[0].OpCode=OpCodes.Nop;refresh.Body.Instructions[0].Operand=null;using(var stream=new MemoryStream()){m.Write(stream);corrupt=stream.ToArray();}}Reject(()=>ThemePatcher.IsUnlocked(corrupt),"tampered theme method rejected by marker checks");
        string legacy=Child(root,"legacy",LegacyEngine.Inspect(original).Patched);Directory.CreateDirectory(FileSafety.BackupRoot(legacy));File.WriteAllBytes(Path.Combine(FileSafety.BackupRoot(legacy),"PCL_v2.99.0.0_原版备份_20261020_163521.bak"),source);FileSafety.Apply(legacy,false,true);Ok(FileSafety.Inspect(legacy,true).Complete,"1.x can upgrade directly to download plus themes");FileSafety.Restore(legacy);Ok(FileSafety.Hash(File.ReadAllBytes(legacy))==hash,"legacy theme upgrade restores original");
        Ok(FileSafety.Hash(File.ReadAllBytes(args[0]))==hash,"user original unchanged after theme suite");Console.WriteLine("THEME_TESTS_OK "+count+" checks; fixture: "+copy);Console.WriteLine("THEME_OUTPUT_SHA256 "+FileSafety.Hash(output));
    }
}
